import sys

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    factors = {}
    for i, value in enumerate(a):
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                e = 0
                while x % d == 0:
                    x //= d
                    e += 1
                factors.setdefault(d, [0] * (n - 1))[i] = e
            d += 1
        if x > 1:
            factors.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for p, exponents in factors.items():
        total = sum(exponents)
        powers = [1] * (n * total + 1)
        for j in range(1, len(powers)):
            powers[j] = powers[j - 1] * p % MOD

        dp = [0] * (total + 1)
        dp[0] = 1
        vertices = 1
        i = 0
        while i < n - 1:
            if exponents[i] == 0:
                j = i
                while j < n - 1 and exponents[j] == 0:
                    j += 1
                run = j - i
                for y in range(total + 1):
                    dp[y] = dp[y] * powers[run * y] % MOD
                vertices += run
                i = j
                continue

            e = exponents[i]
            ndp = [0] * (total + 1)
            for y, w in enumerate(dp):
                if not w:
                    continue
                # The exponent moves upward by e.
                ndp[y + e] = (ndp[y + e] + w * powers[y + e]) % MOD
                # Or it moves downward; renormalize if a new minimum is made.
                if y < e:
                    ndp[0] = (ndp[0] + w * powers[(e - y) * vertices]) % MOD
                else:
                    ndp[y - e] = (ndp[y - e] + w * powers[y - e]) % MOD
            dp = ndp
            vertices += 1
            i += 1

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)

if __name__ == "__main__":
    solve()

