from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # A pair is represented as (smaller endpoint, larger endpoint), and
        # becomes relevant when the right endpoint is reached.
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        # Among all pairs seen so far, retain the two largest left endpoints
        # (with different pair identities).
        first_value, first_id = 0, -1
        second_value, second_id = 0, -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in ending[right]:
                if left > first_value:
                    second_value, second_id = first_value, first_id
                    first_value, first_id = left, idx
                elif left > second_value:
                    second_value, second_id = left, idx

            # Without removing a pair, valid starts for a subarray ending at
            # 'right' are first_value + 1 through right.
            total += right - first_value

            # Only the pair currently supplying the largest endpoint can help
            # at this right endpoint; its improvement is the gap to the second.
            if first_id != -1:
                gains[first_id] += first_value - second_value

        return total + max(gains)

