import sys

def main():
    vals = list(map(int, sys.stdin.buffer.read().split()))
    if not vals:
        return
    it = iter(vals)
    n, m, q = next(it), next(it), next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it)-1, next(it)-1, next(it)))

    queries = []
    closed = [False] * m
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            e = next(it) - 1
            queries.append((1, e))
            closed[e] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if not closed[e] and c < dist[a][b]:
            dist[a][b] = dist[b][a] = c

    for k in range(n):
        rowk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            rowi = dist[i]
            for j in range(n):
                v = dik + rowk[j]
                if v < rowi[j]:
                    rowi[j] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            v = dist[query[1]][query[2]]
            answers.append(str(v if v < INF else -1))
        else:
            a, b, w = edges[query[1]]
            # If the new edge is no shorter than the existing route, it changes nothing.
            if dist[a][b] <= w:
                continue
            da = [dist[i][a] for i in range(n)]
            db = [dist[i][b] for i in range(n)]
            rowa = dist[a][:]
            rowb = dist[b][:]
            for i in range(n):
                row = dist[i]
                x, y = da[i], db[i]
                for j in range(n):
                    v = x + w + rowb[j]
                    z = y + w + rowa[j]
                    if z < v:
                        v = z
                    if v < row[j]:
                        row[j] = v

    sys.stdout.write('\n'.join(reversed(answers)))

