def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = []
    hi = 10**30
    k = 2
    for _ in range(n):
        a, p, b, q = data[k:k + 4]
        k += 4
        machines.append((a, p, b, q))
        hi = min(hi, max(a, b) * budget // min(p, q) + 1)

    def minimum_cost(target, machine):
        a, p, b, q = machine
        best = 10**30
        # If A units of T are no cheaper than B units of S,
        # an optimum uses fewer than A T machines.
        if p * b <= q * a:
            for t in range(a):
                s = max(0, (target - b * t + a - 1) // a)
                value = s * p + t * q
                if value < best:
                    best = value
        else:
            # Symmetric case: fewer than B S machines suffice.
            for s in range(b):
                t = max(0, (target - a * s + b - 1) // b)
                value = s * p + t * q
                if value < best:
                    best = value
        return best

    lo = 0
    while hi - lo > 1:
        mid = (lo + hi) // 2
        total = 0
        for machine in machines:
            total += minimum_cost(mid, machine)
            if total > budget:
                break
        if total <= budget:
            lo = mid
        else:
            hi = mid
    print(lo)


