class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1_000_000_007
        L = len(s)

        # Binomial coefficients, modulo MOD.
        comb = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If x > 1 has t set bits, its reduction depth is one plus
        # the reduction depth of t.  Thus t must reach 1 in < k steps.
        good = []
        for t in range(1, L + 1):
            y = t
            depth = 0
            while y != 1:
                y = y.bit_count()
                depth += 1
            if depth < k:
                good.append(t)

        # Count, for each allowed popcount, binary strings strictly less
        # than s by scanning the first position where they become smaller.
        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = L - i - 1
                for t in good:
                    need = t - used
                    if 0 <= need <= remaining:
                        answer = (answer + comb[remaining][need]) % MOD
                used += 1

        return answer

