    def countKReducibleNumbers(self,s,k):
        MOD=10**9+7
        L=len(s)
        C=[[0]*(L+1) for _ in range(L+1)]
        for i in range(L+1):
            C[i][0]=C[i][i]=1
            for j in range(1,i): C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD
        good=[]
        for t in range(1,L+1):
            x=t; d=0
            while x!=1:
                x=x.bit_count(); d+=1
            if d<=k-1: good.append(t)
        ans=0; ones=0
        for i,ch in enumerate(s):
            if ch=='1':
                rem=L-i-1
                for t in good:
                    if t>=ones and t-ones<=rem:
                        ans=(ans+C[rem][t-ones])%MOD
                ones+=1
