import sys

def bad(a,b):
    # exact feasibility test for two people, restricted to their endpoint vertices
    s1,t1=a; s2,t2=b
    vs=[s1,t1,s2,t2]
    mp={x:i for i,x in enumerate(vs)}
    p=list(range(4))
    def find(x):
        while p[x]!=x:
            p[x]=p[p[x]]; x=p[x]
        return x
    def un(x,y):
        x=find(x); y=find(y)
        if x!=y:p[y]=x
    un(mp[s1],mp[t1]); un(mp[s2],mp[t2])
    edges=[]
    for s,t in ((s1,t1),(s2,t2)):
        l=min(s,t); r=max(s,t)
        # direction of strict inequality: endpoint value < interior for forward
        if s<t: u,v=s,t
        else: u,v=t,s # value at t(original) < interior? for backward interior < endpoint
        for x in vs:
            if l<x<r:
                if s<t: edges.append((mp[u],mp[x]))
                else: edges.append((mp[x],mp[u]))
    # compress and detect directed cycle
    g=[set() for _ in range(4)]
    for x,y in edges:
        x=find(x); y=find(y)
        if x==y:return True
        g[x].add(y)
    st=[0]*4
    def dfs(x):
        st[x]=1
        for y in g[x]:
            if st[y]==1:return True
            if st[y]==0 and dfs(y):return True
        st[x]=2
        return False
    return any(st[i]==0 and dfs(i) for i in range(4))

