    for _ in range(m): a.append((data[z],data[z+1])); z+=2
    nxt=[m+1]*m
    # Pairwise fallback; exact, but may be expensive on maximal adversarial input.
    for i in range(m):
        for j in range(i+1,m):
            if bad(a[i],a[j]):
                nxt[i]=j; break
    # suffix minimum of second endpoint among conflicts starting at/after L
