import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    rows = data[1:]
    total = n * n
    INF = 10**9
    dist = [INF] * total
    inc = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    heap = []
    maxheap = []
    finite = 0

    def setdist(k, d):
        nonlocal finite
        if d < dist[k]:
            if dist[k] == INF:
                finite += 1
            dist[k] = d
            heapq.heappush(heap, (d, k))
            heapq.heappush(maxheap, (-d, k))

    for i in range(n):
        setdist(i * n + i, 0)
        row = rows[i]
        for j, ch in enumerate(row):
            if ch != 45:  # '-'
                c = ch - 97
                out[i][c].append(j)
                inc[j][c].append(i)
                setdist(i * n + j, 1)

    while heap:
        d, state = heapq.heappop(heap)
        if dist[state] != d:
            continue
        if finite == total:
            while maxheap and -maxheap[0][0] != dist[maxheap[0][1]]:
                heapq.heappop(maxheap)
            if d + 2 >= -maxheap[0][0]:
                continue
        x, y = divmod(state, n)
        nd = d + 2
        for c in range(26):
            left = inc[x][c]
            right = out[y][c]
            if not left or not right:
                continue
            for u in left:
                base = u * n
                for v in right:
                    k = base + v
                    if nd < dist[k]:
                        setdist(k, nd)

    for i in range(n):
        print(*(-1 if x == INF else x for x in dist[i*n:(i+1)*n]))

if __name__ == '__main__':
    main()

