import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    H = next(it)
    W = next(it)
    X = next(it)
    P = next(it) - 1
    Q = next(it) - 1
    strength = [next(it) for _ in range(H * W)]

    start = P * W + Q
    current = strength[start]
    seen = bytearray(H * W)
    seen[start] = 1
    heap = []

    def add(r, c):
        k = r * W + c
        if not seen[k]:
            seen[k] = 1
            heapq.heappush(heap, (strength[k], k))

    if P > 0:
        add(P - 1, Q)
    if P + 1 < H:
        add(P + 1, Q)
    if Q > 0:
        add(P, Q - 1)
    if Q + 1 < W:
