import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    a = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        q = None
        for i in range(rank, n):
            if (a[i] >> col) & 1:
                q = i
                break
        if q is None:
            continue
        a[rank], a[q] = a[q], a[rank]
        for i in range(rank + 1, n):
            if (a[i] >> col) & 1:
                a[i] ^= a[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    null_vectors = []
    for f in free:
        x = 1 << f
        for j in range(rank - 1, -1, -1):
            if (a[j] & x).bit_count() & 1:
                x |= 1 << pivots[j]
        null_vectors.append(x)

    ans = [0] * n
    for b, x in enumerate(null_vectors):
        for i in range(n):
            if (x >> i) & 1:
                ans[i] |= 1 << b

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)

if __name__ == '__main__':
    main()

