N = int(sys.stdin.readline())

# Let d = x - y.  Since y > 0, d^3 < N.
# Find the largest integer whose cube is strictly less than N.
lo, hi = 0, 1
while hi ** 3 < N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 < N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d != 0:
        continue
    m = N // d
    # N/d = 3y^2 + 3dy + d^2; solve this quadratic for y.
    disc = 12 * m - 3 * d * d
    root = math.isqrt(disc)
    if root * root != disc:
        continue
    if (root - 3 * d) % 6 != 0:
        continue
    y = (root - 3 * d) // 6
    if y > 0:
        print(y + d, y)
        break
else:
    print(-1)

