        row_rank[x] = rank
    for rank, x in enumerate(q, 1):
        col_rank[x] = rank
    ans = []
    for i in range(1, n + 1):
        r = row_rank[i]
        row = []
        for j in range(1, n + 1):
            # The exceptional corner is not needed for correctness, but
            # keeping it zero also preserves both strict orders.
            if r == n and col_rank[j] == n:
                row.append('0')
            else:
                row.append('1' if r + col_rank[j] >= n + 1 else '0')
        ans.append(''.join(row))
    sys.stdout.write('\n'.join(ans))

