from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        directions = ((1, 1), (1, -1), (-1, -1), (-1, 1))
        size = n * m

        # no_turn[d][p][cell], where p=0 means expected 2 and p=1 means expected 0
        no_turn = [[[0] * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(directions):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for i in rows:
                for j in cols:
                    idx = i * m + j
                    ni, nj = i + dr, j + dc
                    for p, wanted in enumerate((2, 0)):
                        if grid[i][j] == wanted:
                            length = 1
                            if 0 <= ni < n and 0 <= nj < m:
                                length += no_turn[d][1 - p][ni * m + nj]
                            no_turn[d][p][idx] = length

        # one_turn contains paths which may still make one clockwise turn.
        one_turn = [[[0] * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(directions):
            clockwise = (d + 1) % 4
            tr, tc = directions[clockwise]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            for i in rows:
                for j in cols:
