from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = k
        odd = sum(i & 1 for i in range(1, n + 1))
        even = n - odd

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        # Number of parity sequences possible after the indicated last parity.
        # last: 1 means odd, 0 means even, -1 means no previous element.
        @lru_cache(None)
        def parity_ways(o: int, e: int, last: int) -> int:
            if o + e == 0:
                return 1
            result = 0
            if o and last != 1:
                result += parity_ways(o - 1, e, 1)
            if e and last != 0:
                result += parity_ways(o, e - 1, 0)
            return min(cap, result)

        total = min(cap, parity_ways(odd, even, -1) * fact[odd] * fact[even])
        if total < k:
            return []

        remaining = list(range(1, n + 1))
        answer = []
        last = -1
        o, e = odd, even

        for _ in range(n):
            for index, value in enumerate(remaining):
                parity = value & 1
                if last != -1 and parity == last:
                    continue
                no = o - (parity == 1)
                ne = e - (parity == 0)
                block = min(cap, parity_ways(no, ne, parity) * fact[no] * fact[ne])
                if k > block:
                    k -= block
                else:
                    answer.append(value)
                    remaining.pop(index)
                    o, e, last = no, ne, parity
                    break

        return answer

