class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # powers[i] is 10**i modulo k.  A digit in position i of
        # the first half contributes at positions i and n-1-i.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(half):
            if i == n - 1 - i:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[n - 1 - i]) % k)

        # possible[i][r] says that positions i and later can contribute
        # residue r.  Each row is a compact byte array since k <= 9.
        possible = [bytearray(k) for _ in range(half + 1)]
        possible[half][0] = 1
        for i in range(half - 1, -1, -1):
            row = possible[i]
            following = possible[i + 1]
            c = coeff[i]
            first = 1 if i == 0 else 0
            for digit in range(first, 10):
                shift = digit * c % k
                for residue in range(k):
                    if following[residue]:
                        row[(shift + residue) % k] = 1

        # Greedily choose the largest digit whose remainder can be completed.
        chosen = []
        current = 0
        for i, c in enumerate(coeff):
            first = 1 if i == 0 else 0
            for digit in range(9, first - 1, -1):
                needed = (-current - digit * c) % k
                if possible[i + 1][needed]:
                    chosen.append(str(digit))
                    current = (current + digit * c) % k
                    break

        left = ''.join(chosen)
        if n % 2 == 0:
            return left + left[::-1]
        return left + left[-2::-1]

