from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        LOG = n.bit_length()
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        up = [nxt]
        ag = [[nums[i] * (nxt[i] - i) for i in range(n)] + [0]]
        for _ in range(1, LOG):
            pu, pa = up[-1], ag[-1]
            u = [n] * n
            a = [0] * (n + 1)
            for i in range(n):
                m = pu[i]
                u[i] = pu[m] if m < n else n
                a[i] = pa[i] + (pa[m] if m < n else 0)
            up.append(u)
            ag.append(a)

        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        def cost(left, right):
            end = right + 1
            cur = left
            total = 0
            for p in range(LOG - 1, -1, -1):
                if cur == n:
                    break
                e = up[p][cur]
                if e <= end:
                    total += ag[p][cur]
                    cur = e
            if cur < end:
                total += nums[cur] * (end - cur)
            return total - (pref[end] - pref[left])

        answer = 0
        for right in range(n):
            lo, hi = 0, right + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, right) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += right - lo + 1
        return answer

