class Solution:
    def makeStringGood(self, s: str) -> int:
        a = [0] * 26
        for ch in s:
            a[ord(ch) - 97] += 1
        m = max(a)
        ans = len(s)
        cand = set(range(1, min(m, 150) + 1))
        for v in a:
            for d in range(-3, 4):
                if 1 <= v + d <= m:
                    cand.add(v + d)

        for k in cand:
            # This is also a useful bound for large target frequencies.
            base = sum(min(x, abs(x-k)) for x in a)
            if k > 150:
                ans = min(ans, base)
                continue
            inf = 10**9
            dp = [inf] * (k + 1)
            dp[0] = 0
            for z in a:
                nd = [inf] * (k + 1)
                for incoming, old in enumerate(dp):
                    if old == inf:
                        continue
                    q = z + incoming
                    for final in (0, k):
                        # y is the amount changed to the next letter.
                        for y in range(k + 1):
                            if q >= final + y:
                                cost = q - final
                            else:
                                cost = final + 2*y - q
                            val = old + cost
                            if val < nd[y]:
                                nd[y] = val
                dp = nd
            ans = min(ans, min(dp[y] + y for y in range(k + 1)))
        return ans

