    initial_t = (1 << n) - 1
    initial_a = ((1 << m) - 1) << n

    @lru_cache(maxsize=None)
    def winning(turn, t_hand, a_hand):
        hand = t_hand if turn == 0 else a_hand
        if hand == 0:
            return False

        table = all_mask ^ t_hand ^ a_hand
        remaining = hand
        while remaining:
            played = remaining & -remaining
            i = played.bit_length() - 1
            remaining -= played

            if turn == 0:
                nt, na = t_hand ^ played, a_hand
            else:
                nt, na = t_hand, a_hand ^ played

            # Play the card without taking anything.
            if not winning(turn ^ 1, nt, na):
