            candidates = table
            while candidates:
                taken = candidates & -candidates
                j = taken.bit_length() - 1
                candidates -= taken
                if values[j] < values[i]:
                    if turn == 0:
                        nnt, nna = nt | taken, na
                    else:
                        nnt, nna = nt, na | taken
                    if not winning(turn ^ 1, nnt, nna):
                        return True

        return False

    print("Takahashi" if winning(0, initial_t, initial_a) else "Aoki")

