    nxt = [-1] * n
    for v in reversed(order):
        best = -1
        for u, w in g[v]:
            if parent[u] == v and w + down[u] > best:
                best = w + down[u]
                nxt[v] = u
        if best >= 0:
            down[v] = best

    heap = []
    for u, w in g[0]:
        if parent[u] == 0:
            heapq.heappush(heap, (-(w + down[u]), u))

    total = 0
    out = []
    for _ in range(n):
        if heap:
            neg, v = heapq.heappop(heap)
