class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)
        inf = n + 1

        def occurrences(pattern):
            if not pattern:
                return [True] * (n + 1)
            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            result = [False] * (n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result[i - m + 1] = True
                    j = prefix[j - 1]
            return result

        def next_occurrence(flags):
            result = [inf] * (n + 1)
            next_pos = inf
            for i in range(n, -1, -1):
                if flags[i]:
                    next_pos = i
                result[i] = next_pos
            return result

        first_occurs = occurrences(first)
        middle_next = next_occurrence(occurrences(middle))
        last_next = next_occurrence(occurrences(last))

        answer = inf
        first_len, middle_len, last_len = len(first), len(middle), len(last)
        for start in range(n + 1):
            if not first_occurs[start]:
                continue
            middle_start_pos = start + first_len
            if middle_start_pos > n:
                continue
            middle_start = middle_next[middle_start_pos]
            if middle_start > n:
                continue
            last_start_pos = middle_start + middle_len
            if last_start_pos > n:
                continue
            last_start = last_next[last_start_pos]
            if last_start <= n:
                answer = min(answer, last_start + last_len - start)

        return -1 if answer == inf else answer

