from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        order = []
        stack = [(0, 0)]
        while stack:
            x, k = stack[-1]
            if k < len(children[x]):
                stack[-1] = (x, k + 1)
                stack.append((children[x][k], 0))
            else:
                order.append(x)
                stack.pop()

        pos = [0] * n
        chars = [''] * n
        for i, x in enumerate(order):
            pos[x] = i
            chars[i] = s[x]

        size = [1] * n
        for x in order:
            if parent[x] != -1:
                size[parent[x]] += size[x]

        a = ''.join(chars)
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and a[i-k] == a[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and a[i-k-1] == a[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for x in range(n):
            length = size[x]
            start = pos[x] - length + 1
            if length & 1:
                answer[x] = odd[start + length // 2] >= length // 2 + 1
            else:
                answer[x] = even[start + length // 2] >= length // 2
        return answer

