class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For each prefix-index residue, retain the smallest prefix sum seen.
        minimum = [None] * k
        minimum[0] = 0
        prefix = 0
        best = None

        for index, value in enumerate(nums, 1):
            prefix += value
            residue = index % k
            old = minimum[residue]
            if old is not None:
                candidate = prefix - old
                if best is None or candidate > best:
                    best = candidate
            if old is None or prefix < old:
                minimum[residue] = prefix

