import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            q = 3
            while q * q <= x:
                if x % q == 0:
                    return False
                q += 2
            return True

        if is_prime(n) or is_prime(m):
            return -1

        digits = len(str(n))
        limit = 10 ** digits
        infinity = 10 ** 30
        distance = [infinity] * limit
        distance[n] = n
        heap = [(n, n)]
        powers = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit < 9:
                    nxt = value + power
                    if not is_prime(nxt):
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - power
                    if not is_prime(nxt):
                        new_cost = cost + nxt
                        if new_cost < distance[nxt]:
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
        return -1

