from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z-values for the whole array: z[i] is the LCP of nums and nums[i:].
        base = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                base[i] = min(right - i + 1, base[i - left])
            while i + base[i] < n and nums[base[i]] == nums[i + base[i]]:
                base[i] += 1
            if i + base[i] - 1 > right:
                left, right = i, i + base[i] - 1

        answer = 0
        for i in range(1, n - 1):
            first = base[i] >= i
            m = n - i
            z = [0] * m
            left = right = 0
            # If the first condition holds, only lengths k<i need testing
            # for the second condition; lengths k>=i are already counted.
            limit = i if first else m
            for k in range(1, limit):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])
