from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        target = set(targetIndices)
        m = len(pattern)
        inf = m + 1
        # dp[j] is the minimum number of target characters used by a
        # subsequence matching pattern[:j] among the source prefix seen so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if i in target else 0
            for j in range(m - 1, -1, -1):
                if ch == pattern[j] and dp[j] < inf:
                    candidate = dp[j] + cost
                    if candidate < dp[j + 1]:
                        dp[j + 1] = candidate

        # Every target index not needed by an embedding can be removed.
        return len(targetIndices) - dp[m]

