from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse edges so that reachability to node 0 becomes traversal from 0.
        reverse = [[] for _ in range(n)]
        weights = []
        for a, b, w in edges:
            reverse[b].append((a, w))
            weights.append(w)

        if not weights:
            return -1
        candidates = sorted(set(weights))

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        if not feasible(candidates[-1]):
            return -1

        left, right = 0, len(candidates) - 1
        while left < right:
            mid = (left + right) // 2
            if feasible(candidates[mid]):
                right = mid
            else:
                left = mid + 1
        return candidates[left]

