class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        best_gain = 0
        t = '1' + s + '1'
        i = 1

        while i < len(t) - 1:
            if t[i] == '0':
                i += 1
                continue

            # Find this maximal block of ones.
            start = i
            while i < len(t) and t[i] == '1':
                i += 1

            # It is tradable only when both neighboring blocks are zeros.
            if t[start - 1] == '0' and i < len(t) and t[i] == '0':
                left = start - 1
                while t[left] == '0':
                    left -= 1
                right = i
                while t[right] == '0':
                    right += 1
                gain = (start - 1 - left) + (right - i)
                if gain > best_gain:
                    best_gain = gain

        return base + best_gain

