                return 0
            left = 0
            cons = 0
            last = [-1] * 5
            ans = 0
            mp = {'a':0, 'e':1, 'i':2, 'o':3, 'u':4}
            for right, ch in enumerate(word):
                if ch in mp:
                    last[mp[ch]] = right
                else:
                    cons += 1
                while cons > K:
                    if word[left] not in mp:
                        cons -= 1
                    left += 1
                m = min(last)
                if m >= left:
                    ans += m - left + 1
            return ans
        return atmost(k) - atmost(k - 1)

